int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t max_pairs) {
    size_t count = 0;
    const char *pair = in;

    while (count < max_pairs && pair && *pair) {
        const char *eq = strchr(pair, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - pair);
        keys_out[count] = malloc(klen + 1);
        if (!keys_out[count]) return -1;
        strncpy(keys_out[count], pair, klen);
        keys_out[count][klen] = '\0';

        const char *val_start = eq + 1;
        while (*val_start == ' ') val_start++; // Skip leading spaces

        if (*val_start == '"') {
            const char *quote_end = strchr(val_start + 1, '"');
            if (!quote_end) {
                for (size_t i = 0; i <= count; ++i) free(keys_out[i]);
                return -1; // Missing closing quote
            }
            size_t vlen = (size_t)(quote_end - val_start - 1);
            vals_out[count] = malloc(vlen + 1);
            if (!vals_out[count]) {
                for (size_t i = 0; i <= count; ++i) free(keys_out[i]);
                return -1;
            }
            strncpy(vals_out[count], val_start + 1, vlen);
            vals_out[count][vlen] = '\0';
            pair = quote_end + 1;
        } else {
            const char *next_eq = strchr(val_start, '=');
            if (!next_eq) next_eq = eq + strlen(eq); // End of string or next '='
            size_t vlen = (size_t)(next_eq - val_start);
            vals_out[count] = malloc(vlen + 1);
            if (!vals_out[count]) {
                for (size_t i = 0; i <= count; ++i) free(keys_out[i]);
                return -1;
            }
            strncpy(vals_out[count], val_start, vlen);
            vals_out[count][vlen] = '\0';
            pair = next_eq;
        }

        count++;
    }

    return count;
}

