static int _write_pair(char *out, size_t out_sz, const char *k, const char *v) {
    int n = snprintf(out, out_sz, "%s=%s", k, v);
    return (n > 0 && (size_t)n < out_sz) ? 0 : -1;
}

void logfmt_trim(char *s) {
    if (!s || !*s) return;

    // Find the end of the string
    char *end = s + strlen(s);

    // Move the end pointer back until it points to a non-space character
    while (end > s && isspace((unsigned char)*(end - 1))) {
        end--;
    }

    // Null-terminate the string at the new end position
    *end = '\0';
}

int logfmt_format(char *out, size_t out_sz, const char *key, const char *val) {
    return _write_pair(out, out_sz, key, val);
}

int logfmt_copy(char *dst, size_t dst_sz, const char *src) {
    if (dst_sz == 0) return -1;
    if (strlen(src) < dst_sz - 1) {
        strcpy(dst, src);
        return 0;
    }
    strncpy(dst, src, dst_sz - 1);
    dst[dst_sz - 1] = '\0';
    return 0;
}

int logfmt_copy_upper(char *dst, size_t dst_sz, const char *src) {
    if (dst_sz == 0) return -1;
    for (size_t i = 0; i < dst_sz - 1 && src[i]; ++i) {
        dst[i] = toupper(src[i]);
    }
    dst[dst_sz - 1] = '\0';
    return 0;
}

int logfmt_parse(const char *in, char *key_out, size_t k_sz, char *val_out, size_t v_sz) {
    const char *eq = strchr(in, '=');
    if (!eq) return -1;
    size_t klen = (size_t)(eq - in);
    if (klen >= k_sz) klen = k_sz - 1;
    strncpy(key_out, in, klen);
    key_out[klen] = '\0';

    const char *val_start = eq + 1;
    while (*val_start == ' ') val_start++; // Skip leading spaces

    if (*val_start == '"') {
        const char *quote_end = strchr(val_start + 1, '"');
        if (!quote_end) return -1; // Missing closing quote
        size_t vlen = (size_t)(quote_end - val_start - 1);
        if (vlen >= v_sz) vlen = v_sz - 1;
        strncpy(val_out, val_start + 1, vlen);
        val_out[vlen] = '\0';
    } else {
        const char *next_eq = strchr(val_start, '=');
        if (!next_eq) next_eq = eq + strlen(eq); // End of string or next '='
        size_t vlen = (size_t)(next_eq - val_start);
        if (vlen >= v_sz) vlen = v_sz - 1;
        strncpy(val_out, val_start, vlen);
        val_out[vlen] = '\0';
    }

    return 0;
}

int logfmt_format_ts(char *out, size_t out_sz, const char *key, const char *val, long ts) {
    int n = snprintf(out, out_sz, "%s=%s ts=%ld", key, val, ts);
    return (n > 0 && (size_t)n < out_sz) ? 0 : -1;
}

size_t logfmt_len(const char *key, const char *val) {
    return strlen(key) + strlen(val) + 2; // +2 for '=' and null terminator
}

size_t logfmt_len_ts(const char *key, const char *val, long ts) {
    return strlen(key) + strlen(val) + sizeof(ts) + 6; // +6 for ' ts=' and null terminator
}

int logfmt_append(char *buf, size_t buf_sz, const char *key, const char *val) {
    size_t len = strlen(buf);
    if (len + 1 >= buf_sz) return -1; // No space for new key=value pair

    if (len > 0 && buf[len - 1] != ' ') {
        buf[len++] = ' ';
    }

    int ret = _write_pair(&buf[len], buf_sz - len, key, val);
    if (ret == 0) {
        len += strlen(&buf[len]) + 1; // Account for added key=value pair
    }
    return ret;
}

