int logfmt_join(char *out, size_t out_sz, const char *a, const char *b, char sep) {
    if (a == NULL || b == NULL) return -1;
    size_t len_a = strlen(a);
    size_t len_b = strlen(b);
    if (len_a + len_b + 2 >= out_sz) return -1; // +2 for separator and null terminator
    strncpy(out, a, len_a);
    out[len_a] = sep;
    strncpy(&out[len_a + 1], b, len_b);
    out[len_a + len_b + 1] = '\0';
    return 0;
}
